`+t("Transcript")+s("Tab  za  Enter","fold or unfold tool output and reasoning")+s("/ ? n N","search (smart case)")+s("gx","open the link under the cursor in a new tab")+s("v V y yy","select and copy")+s("Enter on a diagram","interact: hjkl pan, +/- zoom, 0 reset, Esc leaves")+s("click in a diagram","pick an item; it lands in the prompt as context")+`
`+t("Sessions")+s("Ctrl-Space h / l","focus the rail / back (the browser keeps Ctrl-w)")+s("j k 3j g G 5G","move; the main view previews")+s("Enter, double-click","switch to the session (resuming it); a host heading starts one")+s("zh","show or hide subagents finished over 5 min ago")+s("y  S  r","copy id, hide rail, refresh")+`
`+t("Prompt")+s("i a","type; Enter sends, Shift-Enter or Ctrl-j newline, Esc leaves")+s("\u2191 \u2193 in an empty prompt","recall queued messages first, or browse history if none")+s("Enter / Esc in queued edit","save in place / discard changes")+s("Ctrl-Enter","send now: every waiting message starts at once, as one")+s("Tab","complete the path before the cursor; a menu offers several matches")+s("Shift-Tab","thinking effort (the model name's color)")+s("Ctrl-c","interrupt the running turn")+`
`+t("Commands")+s(":new  :model [id]  :host user@box[:/dir]","new session, model, add an SSH host")+s(":restart  :rail  :help","restart the hub, toggle rail, this")+t("Questions")+s("i, when the agent asks","answer its form: Tab fields, Enter next, Ctrl-Enter next form or submit")+s("o, or reply in words","type an answer instead: your next message answers the form")+s("Esc","back to the chat; the form waits")+`

